def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Count all past interactions where agent was recipient with this partner
    donations = 0
    interactions = 0
    for entry in my_history:
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            interactions += 1
            if entry["partner_action"] == "donate":
                donations += 1
    if interactions == 0:
        return True  # cooperate on first interaction
    # Donate if partner donated in the majority of interactions
    return donations > interactions / 2

