def strategy(
    agent_id: int,
    my_history: list[dict],
    observations: list[dict],
    round_num: int,
    recipient_id: int,
    population_size: int
) -> bool:
    # Tit-for-two-tats: defect only after two consecutive defections from recipient in past interactions
    # Look at my history as recipient with this partner
    defections = 0
    for entry in reversed(my_history):
        if entry["role"] == "recipient" and entry["partner"] == recipient_id:
            if entry["partner_action"] == "not_donate":
                defections += 1
                if defections >= 2:
                    return False
            else:
                # Reset on a donation (cooperation)
                defections = 0
    # If we never saw two consecutive defections, cooperate
    return True
